function editSalesManager(id){const manager=state.salesManagers.find(item=>item.id===id);$('#modalBody').innerHTML=`<h2>Rediger salgschef</h2><form class="form" id="editSalesManagerForm"><label class="wide">Fulde navn<input name="name" value="${esc(manager.name)}" required></label><label class="wide">E-mail<input name="email" type="email" value="${esc(manager.email)}" required></label><label class="wide">Ny adgangskode<input name="password" type="password" minlength="8" placeholder="Lad feltet være tomt for at beholde den nuværende"></label><button class="primary wide">Gem ændringer</button></form>`;$('#editSalesManagerForm').onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/sales-managers/${manager.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});Object.assign(manager,updated);state.trips.forEach(trip=>{if(trip.salesManagerId===manager.id)trip.salesManager=manager.name});$('#modal').close();toast('Salgschefen er opdateret');renderSalesManagers()}catch(error){toast(error.message)}};$('#modal').showModal()}

const newTripBeforeSalesManager=$('#newTrip').onclick;$('#newTrip').onclick=()=>{newTripBeforeSalesManager();const form=$('#createTrip');if(!form)return;form.querySelector('button').insertAdjacentHTML('beforebegin',`<label>Salgschef ved startstedet<select name="salesManagerId"><option value="">Ingen salgschef</option>${(state.salesManagers||[]).map(manager=>`<option value="${manager.id}">${esc(manager.name)}</option>`).join('')}</select></label>`)};

