const tripDriverNameBeforeSalesManager=tripDriverName;tripDriverName=function(id){const trip=state.trip?.trip,manager=state.salesManagers?.find(item=>item.id===id),record=[...(state.trip?.passengers||[]),...(state.trip?.baggage||[])].find(item=>item.cashHolderUserId===id&&item.cashHolderUserName);if(manager)return manager.name;if(record)return record.cashHolderUserName;if(trip&&id===trip.salesManagerId)return trip.salesManager||'Salgschef';return tripDriverNameBeforeSalesManager(id)};

tripCashCards=function(){const trip=state.trip.trip,allStaff=[trip.primaryDriverId,trip.secondaryDriverId,trip.salesManagerId].filter(Boolean),staffIds=state.user.role==='sales_manager'?[state.user.id]:allStaff;return`<div class="cash-custody">${staffIds.map(id=>{const records=[...state.trip.passengers,...state.trip.baggage].filter(record=>record.cashHolderUserId===id&&!record.cashHandedOverAt),dkk=records.filter(record=>(record.paymentCurrency||'DKK')==='DKK').reduce((sum,record)=>sum+Number(record.cashAmount||0),0),eur=records.filter(record=>record.paymentCurrency==='EUR').reduce((sum,record)=>sum+Number(record.cashAmount||0),0);return`<div><span>Uafleverede kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b></div>`}).join('')}</div>`};

settlementCash=function(staffId){const records=[...state.trip.passengers.map(record=>({record,kind:'passenger'})),...state.trip.baggage.map(record=>({record,kind:'baggage'}))].filter(item=>item.record.cashHolderUserId===staffId&&['bus','departure'].includes(item.record.paymentLocation)&&!item.record.cashHandedOverAt);return{records,DKK:records.filter(item=>(item.record.paymentCurrency||'DKK')==='DKK').reduce((sum,item)=>sum+Number(item.record.cashAmount||0),0),EUR:records.filter(item=>item.record.paymentCurrency==='EUR').reduce((sum,item)=>sum+Number(item.record.cashAmount||0),0)}};

settlementDriverCard=function(staffId,all){const cash=settlementCash(staffId),pending=all.find(settlement=>settlement.driverId===staffId&&settlement.status==='pending'),canSubmit=(['driver','sales_manager'].includes(state.user.role)&&state.user.id===staffId)||state.user.role==='admin';return`<section class="settlement-card"><header><div class="avatar">${esc(tripDriverName(staffId).split(' ').map(part=>part[0]).slice(0,2).join(''))}</div><div><small>Kontanter hos</small><h3>${esc(tripDriverName(staffId))}</h3></div>${pending?'<span class="settlement-status pending">Afventer godkendelse</span>':'<span class="settlement-status open">Ikke afleveret</span>'}</header><div class="expected-cash"><div><span>Forventet DKK</span><strong>${money(cash.DKK,'DKK')}</strong></div><div><span>Forventet EUR</span><strong>${money(cash.EUR,'EUR')}</strong></div><small>${cash.records.length} betalinger</small></div>${pending?`<div class="pending-settlement"><span>Indberettet</span><strong>${money(pending.delivered.DKK,'DKK')} · ${money(pending.delivered.EUR,'EUR')}</strong><small>${date(pending.submittedAt)}</small></div>`:cash.records.length&&canSubmit?`<form class="form settlement-form" data-settlement-form="${staffId}"><label>Afleveret DKK<input name="deliveredDKK" type="number" min="0" step="0.01" value="${cash.DKK}" required></label><label>Afleveret EUR<input name="deliveredEUR" type="number" min="0" step="0.01" value="${cash.EUR}" required></label><label class="wide">Forklaring ved difference<textarea name="note"></textarea></label><button class="primary wide">Indsend til godkendelse</button></form>`:'<div class="settlement-empty">Ingen uafstemte kontanter</div>'}</section>`};

renderSettlementTab=function(){const trip=state.trip.trip,all=state.trip.settlements||[],staffIds=[trip.primaryDriverId,trip.secondaryDriverId,trip.salesManagerId].filter(Boolean),visibleIds=state.user.role==='admin'?staffIds:[state.user.id];$('#tabContent').innerHTML=`<div class="settlement-intro"><div><small>KONTANTAFSTEMNING</small><h2>Aflevering fra personale til kontor</h2><p>Betalinger modtaget i bussen og ved startstedet afstemmes separat i DKK og EUR.</p></div><span>${esc(trip.title)}<b>${date(trip.departureAt)}</b></span></div><div class="settlement-drivers">${visibleIds.map(staffId=>settlementDriverCard(staffId,all)).join('')}</div><section class="panel settlement-history"><div class="panel-head"><h2>Afstemningshistorik</h2><small>${all.length} afstemninger</small></div>${all.length?`<div class="table-scroll"><table class="list"><thead><tr><th>Medarbejder</th><th>Forventet</th><th>Afleveret</th><th>Difference</th><th>Status</th><th>Behandling</th></tr></thead><tbody>${[...all].reverse().map(settlementRow).join('')}</tbody></table></div>`:'<div class="empty">Ingen kontantafstemninger endnu</div>'}</section>`;wireSettlementTab()};

const tripRendererBeforeSalesManager=renderTrip;renderTrip=function(){tripRendererBeforeSalesManager();if(state.user.role==='sales_manager')$('[data-expense-tab]')?.remove();if(state.user.role!=='admin'||!state.trip?.trip)return;const trip=state.trip.trip,locked=state.trip.passengers.some(passenger=>passenger.checkedIn||passenger.attendanceHistory?.some(event=>event.action==='checked_in')),options=`<option value="">Ingen salgschef</option>${(state.salesManagers||[]).map(manager=>`<option value="${manager.id}" ${manager.id===trip.salesManagerId?'selected':''}>${esc(manager.name)}</option>`).join('')}`,panel=locked?`<section class="trip-sales-assignment locked"><div><small>SALG VED STARTSTEDET</small><strong>${esc(trip.salesManager||'Ingen salgschef')}</strong></div><span>🔒 Låst efter påbegyndt check-in</span></section>`:`<form class="trip-sales-assignment" id="tripSalesManagerAssignment"><div><small>SALG VED STARTSTEDET</small><strong>Tildel salgschef</strong></div><label>Salgschef<select name="salesManagerId">${options}</select></label><button class="mini">Gem salgschef</button></form>`;const anchor=$('.trip-driver-assignment')||$('.detail-hero');anchor.insertAdjacentHTML('afterend',panel);const form=$('#tripSalesManagerAssignment');if(!form)return;form.onsubmit=async event=>{event.preventDefault();try{const updated=await api(`/api/trips/${trip.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});state.trip.trip=updated;const overview=state.trips.find(item=>item.id===trip.id);if(overview)Object.assign(overview,updated);toast('Salgschefen på turen er opdateret');renderTrip()}catch(error){toast(error.message)}}};

