exportPassengerList=function(){const headings=['Navn','Telefon','Opsamling','Destination','Sæde','Check-in','Check-in udført af','Billetstatus','Betaling modtaget af','Begrundelse','Beløb','Valuta'],rows=state.trip.passengers.map(passenger=>[passenger.name,passenger.phone,stopName(passenger.pickupStopId),stopName(passenger.destinationStopId),passenger.seatNumber,passenger.checkedIn?'Checket ind':passenger.attendanceStatus==='no_show'?'Udeblevet':'Afventer',passenger.checkedInByName||'',passenger.paymentStatus==='cash'?'Betalt':passenger.paymentStatus==='free'?'Gratis billet':'Ikke betalt',passenger.cashHolderUserName||passenger.paymentRecordedByName||'',passenger.freeTicketReason||'',passenger.paymentStatus==='cash'?passenger.cashAmount:0,passenger.paymentStatus==='cash'?(passenger.paymentCurrency||'DKK'):'']);const csv=[headings,...rows].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`passagerliste-${state.trip.trip.id}.csv`;link.click();URL.revokeObjectURL(url)};

tripCashCards=function(){const trip=state.trip.trip,records=[...state.trip.passengers,...state.trip.baggage],holderIds=records.filter(record=>record.cashHolderUserId&&!record.cashHandedOverAt).map(record=>record.cashHolderUserId),allStaff=[...new Set([trip.primaryDriverId,trip.secondaryDriverId,trip.salesManagerId,...holderIds].filter(Boolean))],staffIds=state.user.role==='sales_manager'?[state.user.id]:allStaff;return`<div class="cash-custody">${staffIds.map(id=>{const held=records.filter(record=>record.cashHolderUserId===id&&!record.cashHandedOverAt),dkk=held.filter(record=>(record.paymentCurrency||'DKK')==='DKK').reduce((sum,record)=>sum+Number(record.cashAmount||0),0),eur=held.filter(record=>record.paymentCurrency==='EUR').reduce((sum,record)=>sum+Number(record.cashAmount||0),0);return`<div><span>Uafleverede kontanter hos</span><strong>${esc(tripDriverName(id))}</strong><b>${money(dkk,'DKK')} · ${money(eur,'EUR')}</b><small>${held.length} betalinger</small></div>`}).join('')}</div>`};

