// Mobile-first check-in cards. Secondary actions stay close, but out of the way.
checkinCard=function(p){
  const paymentClass=p.paymentStatus==='free'?'free':p.paymentStatus==='cash'?'paid':'unpaid';
  const paymentTitle=p.paymentStatus==='free'?'Gratis billet':p.paymentStatus==='cash'?'Betalt':'Ikke betalt';
  const paymentValue=p.paymentStatus==='free'?(p.freeTicketReason||'Ingen betaling'):p.paymentStatus==='cash'?money(p.cashAmount,p.paymentCurrency||'DKK'):'Betaling mangler';
  const attendance=p.checkedIn?'checked':p.attendanceStatus==='no_show'?'noshow':'pending';
  return `<article class="checkin-card ${p.checkedIn?'is-checked':''} ${p.attendanceStatus==='no_show'?'is-noshow':''}" data-checkin-card="${p.id}" data-checkin-state="${attendance}" data-payment-state="${p.paymentStatus}" data-search="${esc(`${p.name} ${p.phone} ${p.seatNumber} ${stopName(p.pickupStopId)} ${stopName(p.destinationStopId)}`.toLowerCase())}">
    <div class="checkin-seat"><small>SÆDE</small><strong>${p.seatNumber}</strong></div>
    <div class="checkin-person"><h3>${esc(p.name)}</h3><a href="tel:${esc(p.phone)}">${esc(p.phone)}</a><span>${esc(stopName(p.pickupStopId))} → ${esc(stopName(p.destinationStopId))}</span>${p.pendingSync?'<em>Afventer synkronisering</em>':''}</div>
    <div class="checkin-payment ${paymentClass}"><small>${paymentTitle}</small><strong>${esc(paymentValue)}</strong></div>
    <div class="checkin-actions">
      ${p.paymentStatus==='unpaid'?`<button class="pay-button" data-pay-passenger="${p.id}">Betal billet</button>`:''}
      ${!p.checkedIn?`<button class="check-button" data-fast-check="${p.id}">✓ Check ind</button>`:'<span class="checked-label">✓ Checket ind</span>'}
      <a href="tel:${esc(p.phone)}" class="icon-action checkin-call" title="Ring" aria-label="Ring til ${esc(p.name)}">☎</a>
      <details class="checkin-more"><summary aria-label="Flere handlinger">•••</summary><div>
        ${!p.checkedIn&&p.attendanceStatus!=='no_show'?`<button data-no-show="${p.id}">Marker udeblevet</button>`:''}
        <button data-passenger-detail="${p.id}">Se alle detaljer</button>
      </div></details>
    </div>
  </article>`
};

// Combined search and one-touch filters make long passenger lists manageable.
const checkInModeBeforeMobileWorkspace=renderCheckInMode;
renderCheckInMode=function(){
  checkInModeBeforeMobileWorkspace();
  const search=$('#checkinSearch'),sections=$('.checkin-sections');
  if(!search||!sections)return;
  const cards=$$('[data-checkin-card]');
  const counts={
    all:cards.length,
    pending:cards.filter(card=>card.dataset.checkinState==='pending').length,
    unpaid:cards.filter(card=>card.dataset.paymentState==='unpaid').length,
    checked:cards.filter(card=>card.dataset.checkinState==='checked').length
  };
  if(!['all','pending','unpaid','checked'].includes(state.checkInListFilter))state.checkInListFilter='pending';
  const tools=document.createElement('div');
  tools.className='checkin-mobile-tools';
  tools.innerHTML=`<div class="checkin-filter-label"><strong>Vis passagerer</strong><span id="checkinVisibleCount"></span></div><div class="checkin-filter-chips" role="group" aria-label="Filtrer check-in-listen">
    <button data-checkin-filter="pending">Afventer <b>${counts.pending}</b></button>
    <button data-checkin-filter="unpaid">Ikke betalt <b>${counts.unpaid}</b></button>
    <button data-checkin-filter="checked">Checket ind <b>${counts.checked}</b></button>
    <button data-checkin-filter="all">Alle <b>${counts.all}</b></button>
  </div>`;
  search.closest('.checkin-search').insertAdjacentElement('afterend',tools);
  const applyFilters=()=>{
    const query=search.value.trim().toLowerCase();
    let visible=0;
    cards.forEach(card=>{
      const matchesText=!query||card.dataset.search.includes(query);
      const filter=state.checkInListFilter;
      const matchesFilter=filter==='all'||filter==='pending'&&card.dataset.checkinState==='pending'||filter==='unpaid'&&card.dataset.paymentState==='unpaid'||filter==='checked'&&card.dataset.checkinState==='checked';
      card.hidden=!(matchesText&&matchesFilter);
      if(!card.hidden)visible++;
    });
    $$('.checkin-group').forEach(group=>{
      const groupCards=[...group.querySelectorAll('[data-checkin-card]')],shown=groupCards.filter(card=>!card.hidden).length;
      group.hidden=shown===0;
      const badge=group.querySelector('header span');if(badge)badge.textContent=shown;
    });
    $$('#tabContent [data-checkin-filter]').forEach(button=>{const active=button.dataset.checkinFilter===state.checkInListFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});
    const result=$('#checkinVisibleCount');if(result)result.textContent=`${visible} vist`;
  };
  search.oninput=applyFilters;
  $$('#tabContent [data-checkin-filter]').forEach(button=>button.onclick=()=>{state.checkInListFilter=button.dataset.checkinFilter;applyFilters();sections.scrollIntoView({behavior:'smooth',block:'start'})});
  applyFilters();
};

// Advanced per-trip cash flow: ticket cash, baggage cash, expenses and custody.
const reportsBeforeAdvancedTripCash=renderReports;
renderReports=async function(){
  await reportsBeforeAdvancedTripCash();
  if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;
  try{
    const report=await api('/api/reports'),control=$('.economy-control');
    if(!control)return;
    control.insertAdjacentHTML('afterend','<section class="advanced-trip-economy" id="advancedTripEconomy"></section>');
    const refresh=()=>renderAdvancedTripEconomy(report);
    ['#economyFrom','#economyTo','#economyTrip','#economyCurrency'].forEach(selector=>$(selector)?.addEventListener('change',refresh));
    $('#resetEconomy')?.addEventListener('click',()=>setTimeout(refresh));
    refresh();
  }catch(error){toast(error.message)}
};

function economyAmount(rows,path){
  return ['DKK','EUR'].reduce((totals,currency)=>{totals[currency]=rows.reduce((sum,row)=>{let value=row;for(const key of path.split('.'))value=value?.[key];return sum+Number(value?.[currency]||0)},0);return totals},{});
}
function economyValues(amounts,currency,strong=false){
  const currencies=currency==='all'?['DKK','EUR']:[currency];
  return currencies.map(code=>`<span class="currency-value ${code.toLowerCase()}">${strong?'<strong>':''}${money(amounts?.[code]||0,code)}${strong?'</strong>':''}</span>`).join('');
}
function cashStage(label,amounts,currency,kind,note){return`<div class="cash-stage ${kind}"><span>${label}</span>${economyValues(amounts,currency,true)}<small>${note}</small></div>`}
function renderAdvancedTripEconomy(report){
  const host=$('#advancedTripEconomy');if(!host)return;
  const rows=filteredTripResults(report),currency=$('#economyCurrency').value;
  const ticket=economyAmount(rows,'ticketRevenue'),baggage=economyAmount(rows,'baggageRevenue'),expenses=economyAmount(rows,'approvedExpenses'),net=economyAmount(rows,'net'),shop=economyAmount(rows,'cashFlow.shop'),handed=economyAmount(rows,'cashFlow.handedOver'),held=economyAmount(rows,'cashFlow.held');
  const totals={DKK:ticket.DKK+baggage.DKK,EUR:ticket.EUR+baggage.EUR};
  const discrepancy={DKK:totals.DKK-shop.DKK-handed.DKK-held.DKK,EUR:totals.EUR-shop.EUR-handed.EUR-held.EUR},hasDiscrepancy=Math.abs(discrepancy.DKK)>.001||Math.abs(discrepancy.EUR)>.001;
  const currencies=currency==='all'?['DKK','EUR']:[currency];
  const mix=currencies.map(code=>{const total=totals[code]||0,ticketPct=total?Math.round(ticket[code]/total*100):0,baggagePct=total?100-ticketPct:0;return`<div class="revenue-mix-row"><strong>${code}</strong><div class="revenue-mix-bar"><i style="width:${ticketPct}%"></i><b style="width:${baggagePct}%"></b></div><span>Billetter ${ticketPct}%</span><span>Bagage ${baggagePct}%</span></div>`}).join('');
  const holders=new Map();rows.flatMap(row=>row.cashFlow?.byHolder||[]).forEach(holder=>{const current=holders.get(holder.userName)||{name:holder.userName,payments:0,DKK:0,EUR:0};current.payments+=holder.payments;current.DKK+=holder.amounts.DKK;current.EUR+=holder.amounts.EUR;holders.set(holder.userName,current)});
  host.innerHTML=`<header class="advanced-economy-head"><div><small>AVANCERET TURANALYSE</small><h2>Hvor kommer pengene fra – og hvor står de?</h2><p>${rows.length===1?'Viser den valgte tur':`Samlet visning for ${rows.length} ture`}</p></div><span>${currency==='all'?'DKK og EUR':currency}</span></header>${hasDiscrepancy?`<div class="economy-discrepancy"><strong>Kontroladvarsel</strong><span>Registreret salg stemmer ikke med placeringen af kontanterne: ${economyValues(discrepancy,currency,true)}</span></div>`:''}
    <div class="advanced-kpis"><div class="ticket-kpi"><small>Kontanter fra billetter</small>${economyValues(ticket,currency,true)}<em>${rows.reduce((sum,row)=>sum+row.paidTickets,0)} betalte billetter</em></div><div class="baggage-kpi"><small>Kontanter fra bagage</small>${economyValues(baggage,currency,true)}<em>${rows.reduce((sum,row)=>sum+row.paidBaggage,0)} betalte forsendelser</em></div><div class="expense-kpi"><small>Godkendte udgifter</small>${economyValues(expenses,currency,true)}<em>${rows.reduce((sum,row)=>sum+(row.expenseCategories||[]).length,0)} udgiftskategorier</em></div><div class="net-kpi ${currencies.some(code=>net[code]<0)?'negative':'positive'}"><small>Nettoresultat</small>${economyValues(net,currency,true)}<em>Omsætning minus godkendte udgifter</em></div></div>
    <div class="advanced-economy-grid"><section class="cash-flow-panel"><h3>Kontanternes placering</h3><div class="cash-flow-line">${cashStage('Registreret i salgsbutikken',shop,currency,'shop','Allerede hos kontoret')}${cashStage('Afleveret og godkendt',handed,currency,'office','Afstemt fra personale')}${cashStage('Står stadig hos personale',held,currency,'held','Skal kontantafstemmes')}</div>${holders.size?`<div class="cash-holder-breakdown"><strong>Uafleveret per medarbejder</strong>${[...holders.values()].map(holder=>`<div><span>${esc(holder.name)}<small>${holder.payments} betalinger</small></span>${economyValues(holder,currency,true)}</div>`).join('')}</div>`:'<p class="all-settled">✓ Ingen uafleverede kontanter i den valgte visning</p>'}</section><section class="revenue-mix"><h3>Fordeling af kontantsalg</h3>${mix}<div class="mix-total"><span>Samlet kontantsalg</span>${economyValues(totals,currency,true)}</div></section></div>
    <section class="trip-economy-list"><header><h3>Detaljer per tur</h3><span>${rows.length} ture</span></header>${rows.length?rows.map((row,index)=>tripEconomyDetail(row,currency,rows.length===1||index===0)).join(''):'<div class="empty">Ingen ture matcher de valgte filtre</div>'}</section>`;
}
function tripEconomyDetail(row,currency,open){
  const currencies=currency==='all'?['DKK','EUR']:[currency],negative=currencies.some(code=>row.net[code]<0),settlementText=row.cashFlow.held.DKK||row.cashFlow.held.EUR?'Kontanter mangler afstemning':'Kontanter afstemt';
  const categories=(row.expenseCategories||[]).map(item=>`<div><span>${esc(item.category)}</span>${economyValues(item.approved,currency,true)}${(item.pending.DKK||item.pending.EUR)?`<small>Afventer: ${currencies.map(code=>money(item.pending[code],code)).join(' · ')}</small>`:''}</div>`).join('')||'<p>Ingen udgifter på turen</p>';
  return`<details class="trip-economy-detail" ${open?'open':''}><summary><div><strong>${esc(row.title)}</strong><small>${date(row.departureAt)} · ${esc(row.busName)}</small></div><span class="trip-cash-status ${row.cashFlow.held.DKK||row.cashFlow.held.EUR?'attention':'done'}">${settlementText}</span><div class="trip-net ${negative?'negative':'positive'}"><small>Netto</small>${economyValues(row.net,currency,true)}</div><b>⌄</b></summary><div class="trip-economy-body"><div class="trip-money-grid"><div><span>Billetter</span>${economyValues(row.ticketRevenue,currency,true)}<small>${row.paidTickets} betalt · ${row.freeTickets} gratis · ${row.unpaid} ubetalt</small></div><div><span>Bagage</span>${economyValues(row.baggageRevenue,currency,true)}<small>${row.paidBaggage} betalt · ${row.unpaidBaggage} ubetalt</small></div><div><span>Godkendte udgifter</span>${economyValues(row.approvedExpenses,currency,true)}</div><div class="${negative?'negative':'positive'}"><span>Nettoresultat</span>${economyValues(row.net,currency,true)}</div></div><div class="trip-cash-chain">${cashStage('Salgsbutik',row.cashFlow.shop,currency,'shop','Direkte hos kontoret')}${cashStage('Afleveret',row.cashFlow.handedOver,currency,'office',`${row.settlements.approved} godkendte afstemninger`)}${cashStage('Hos personale',row.cashFlow.held,currency,'held',`${row.settlements.pending} afstemninger afventer`)}</div><div class="expense-category-list"><h4>Udgifter efter kategori</h4>${categories}</div></div></details>`
}

exportEconomyCsv=function(rows){const header=['Tur','Dato','Bus','Passagerer','Kapacitet','Belægning %','Billetter DKK','Billetter EUR','Bagage DKK','Bagage EUR','Salgsbutik DKK','Salgsbutik EUR','Afleveret DKK','Afleveret EUR','Hos personale DKK','Hos personale EUR','Godkendte udgifter DKK','Godkendte udgifter EUR','Afventende udgifter DKK','Afventende udgifter EUR','Netto DKK','Netto EUR'],data=rows.map(r=>[r.title,r.departureAt,r.busName,r.passengers,r.seatCount,r.occupancy,r.ticketRevenue.DKK,r.ticketRevenue.EUR,r.baggageRevenue.DKK,r.baggageRevenue.EUR,r.cashFlow.shop.DKK,r.cashFlow.shop.EUR,r.cashFlow.handedOver.DKK,r.cashFlow.handedOver.EUR,r.cashFlow.held.DKK,r.cashFlow.held.EUR,r.approvedExpenses.DKK,r.approvedExpenses.EUR,r.pendingExpenses.DKK,r.pendingExpenses.EUR,r.net.DKK,r.net.EUR]),csv=[header,...data].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='avanceret-turoekonomi.csv';link.click();URL.revokeObjectURL(url)};

// A trip expense folder designed for quick mobile capture and office approval.
function expenseMethodLabel(method){return({company_card:'Firmakort',cash:'Kontanter',private:'Privat udlæg'})[method]||'Kontanter'}
function expenseStatusLabel(status){return status==='approved'?'Godkendt':status==='rejected'?'Afvist':'Afventer'}
function expenseCard(expense){
  const status=expense.status||'pending',method=expense.paymentMethod||'cash',missing=!expense.receiptFile,privatePending=method==='private'&&status==='approved'&&(expense.reimbursementStatus||'pending')!=='paid';
  return`<article class="expense-folder-card" data-expense-card data-expense-status="${status}" data-expense-receipt="${missing?'missing':'attached'}"><div class="expense-card-icon">${missing?'!':'▧'}</div><div class="expense-card-title"><small>${date(expense.expenseDate||expense.createdAt)}</small><h3>${esc(expense.category)}</h3><p>${esc(expense.description||'Ingen beskrivelse')}</p></div><div class="expense-card-amount"><strong>${money(expense.amount,expense.currency)}</strong><span class="expense-status ${status}">${expenseStatusLabel(status)}</span></div><div class="expense-card-meta"><span>${expenseMethodLabel(method)}</span><span>Betalt af <b>${esc(expense.paidByName||expense.createdByName||'Ukendt')}</b></span><span>Registreret af <b>${esc(expense.createdByName||'Ukendt')}</b></span>${method==='private'?`<span class="reimbursement ${expense.reimbursementStatus==='paid'?'paid':'pending'}">${expense.reimbursementStatus==='paid'?'✓ Tilbagebetalt':'Afventer tilbagebetaling'}</span>`:''}</div><div class="expense-receipt ${missing?'missing':''}">${missing?`<strong>Kvittering mangler</strong><label class="attach-receipt">Tilføj kvittering<input type="file" accept="image/*,application/pdf" capture="environment" data-attach-receipt="${expense.id}"></label>`:`<span>Kvittering vedhæftet</span><a href="/api/expenses/${expense.id}/receipt" target="_blank">Åbn bilag ↗</a>`}</div>${expense.reviewNote?`<div class="expense-review-note"><strong>Kommentar</strong><span>${esc(expense.reviewNote)}</span></div>`:''}<div class="expense-card-actions">${state.user.role==='admin'&&status==='pending'?`<button class="mini done" data-approve-expense="${expense.id}" ${missing?'disabled title="Kvittering mangler"':''}>Godkend</button><button class="mini danger" data-reject-expense="${expense.id}">Afvis</button>`:''}${state.user.role==='admin'&&privatePending?`<button class="mini reimburse" data-reimburse-expense="${expense.id}">Marker tilbagebetalt</button>`:''}</div></article>`
}
renderExpensesTab=function(){
  const expenses=state.trip.expenses||[],trip=state.trip.trip,statusTotals=status=>['DKK','EUR'].reduce((totals,currency)=>{totals[currency]=expenses.filter(item=>(item.status||'pending')===status&&item.currency===currency).reduce((sum,item)=>sum+Number(item.amount||0),0);return totals},{}),approved=statusTotals('approved'),pending=statusTotals('pending'),privatePending=expenses.filter(item=>(item.paymentMethod||'cash')==='private'&&(item.reimbursementStatus||'pending')!=='paid'&&(item.status||'pending')!=='rejected'),missing=expenses.filter(item=>!item.receiptFile).length;
  const payerOptions=state.user.role==='admin'?[state.user,...(state.drivers||[]).filter(driver=>[trip.primaryDriverId,trip.secondaryDriverId].includes(driver.id))]:[state.user];
  $('#tabContent').innerHTML=`<section class="expense-folder-hero"><div><small>DIGITAL UDGIFTSMAPPE</small><h2>${esc(trip.title)}</h2><p>${date(trip.departureAt)} · Alle udgifter gemmes direkte på denne tur</p></div><button class="primary" id="jumpExpenseForm">+ Tilføj udgift</button></section><div class="expense-folder-summary"><div><small>Godkendt</small>${economyValues(approved,'all',true)}</div><div><small>Afventer godkendelse</small>${economyValues(pending,'all',true)}</div><div><small>Private udlæg åbne</small><strong>${privatePending.length}</strong></div><div class="${missing?'attention':''}"><small>Mangler kvittering</small><strong>${missing}</strong></div></div><div class="expense-folder-filters"><button class="active" data-expense-filter="all">Alle <b>${expenses.length}</b></button><button data-expense-filter="pending">Afventer <b>${expenses.filter(item=>(item.status||'pending')==='pending').length}</b></button><button data-expense-filter="approved">Godkendt <b>${expenses.filter(item=>item.status==='approved').length}</b></button><button data-expense-filter="rejected">Afvist <b>${expenses.filter(item=>item.status==='rejected').length}</b></button><button data-expense-filter="missing">Mangler kvittering <b>${missing}</b></button></div><div class="expense-folder-layout"><section class="expense-card-list" id="expenseCardList">${expenses.length?expenses.map(expenseCard).join(''):'<div class="empty expense-empty">Ingen udgifter er registreret på turen</div>'}</section><aside class="expense-entry-panel" id="expenseEntryPanel"><header><span>＋</span><div><small>NY TURUDGIFT</small><h3>Registrer udgift</h3></div></header><form class="form" id="expenseForm"><label>Kategori<select name="category"><option>Brændstof</option><option>Vejafgift</option><option>Færge</option><option>Parkering</option><option>Reparation</option><option>Forplejning</option><option>Overnatning</option><option>Andet</option></select></label><label>Beløb<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" required></label><label>Valuta<select name="currency"><option value="DKK">DKK</option><option value="EUR">EUR</option></select></label><label>Betalingsmetode<select name="paymentMethod"><option value="company_card">Firmakort</option><option value="cash">Kontanter</option><option value="private">Privat udlæg</option></select></label><label class="wide">Betalt af<select name="paidByUserId">${payerOptions.map(person=>`<option value="${person.id}">${esc(person.name)}</option>`).join('')}</select></label><label class="wide receipt-capture"><span>Kvittering <small>kan tilføjes senere</small></span><input name="receipt" type="file" accept="image/*,application/pdf" capture="environment"><b>Tag billede eller vælg fil</b><em>PDF eller billede · maks. 5 MB</em></label><label class="wide">Beskrivelse<textarea name="description" placeholder="Hvad blev købt, og hvorfor?"></textarea></label><button class="primary wide">Gem udgift på turen</button></form></aside></div>`;
  $('#expenseForm').onsubmit=uploadExpense;$('#jumpExpenseForm').onclick=()=>$('#expenseEntryPanel').scrollIntoView({behavior:'smooth',block:'start'});
  $$('[data-expense-filter]').forEach(button=>button.onclick=()=>{$$('[data-expense-filter]').forEach(item=>item.classList.toggle('active',item===button));$$('[data-expense-card]').forEach(card=>card.hidden=!(button.dataset.expenseFilter==='all'||card.dataset.expenseStatus===button.dataset.expenseFilter||button.dataset.expenseFilter==='missing'&&card.dataset.expenseReceipt==='missing'))});
  $$('[data-approve-expense]').forEach(button=>button.onclick=()=>reviewExpense(Number(button.dataset.approveExpense),'approved'));$$('[data-reject-expense]').forEach(button=>button.onclick=()=>reviewExpense(Number(button.dataset.rejectExpense),'rejected'));$$('[data-reimburse-expense]').forEach(button=>button.onclick=()=>reimburseExpense(Number(button.dataset.reimburseExpense)));$$('[data-attach-receipt]').forEach(input=>input.onchange=()=>attachExpenseReceipt(Number(input.dataset.attachReceipt),input.files[0]));
};

uploadExpense=async function(event){event.preventDefault();const form=event.target,file=form.receipt.files[0];if(file&&file.size>5*1024*1024)return toast('Kvitteringen må højst fylde 5 MB');try{const payload={category:form.category.value,amount:form.amount.value,currency:form.currency.value,paymentMethod:form.paymentMethod.value,paidByUserId:form.paidByUserId.value,description:form.description.value};if(file)Object.assign(payload,{receiptName:file.name,receiptType:file.type,receiptData:await fileAsDataUrl(file)});const expense=await api(`/api/trips/${state.trip.trip.id}/expenses`,{method:'POST',body:JSON.stringify(payload)});state.trip.expenses.push(expense);toast(file?'Udgiften og kvitteringen er gemt':'Udgiften er gemt · kvittering mangler');renderTrip()}catch(error){toast(error.message)}};
async function attachExpenseReceipt(id,file){if(!file)return;if(file.size>5*1024*1024)return toast('Kvitteringen må højst fylde 5 MB');try{const updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({receiptName:file.name,receiptType:file.type,receiptData:await fileAsDataUrl(file)})});Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast('Kvitteringen er tilføjet');renderTrip()}catch(error){toast(error.message)}}
reviewExpense=async function(id,status){let reviewNote='';if(status==='rejected'){const reason=prompt('Hvorfor afvises udgiften?');if(reason===null)return;reviewNote=reason}try{const updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({status,reviewNote})});if(state.trip?.expenses?.some(item=>item.id===id)){Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');renderTrip()}else{toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');renderReports()}}catch(error){toast(error.message)}};
async function reimburseExpense(id){if(!confirm('Bekræft, at det private udlæg er tilbagebetalt.'))return;try{const updated=await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({reimbursementStatus:'paid'})});Object.assign(state.trip.expenses.find(item=>item.id===id),updated);toast('Udlægget er markeret som tilbagebetalt');renderTrip()}catch(error){toast(error.message)}}

const reportsBeforeMissingReceipts=renderReports;
renderReports=async function(){await reportsBeforeMissingReceipts();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports'),expensePanel=[...$$('.report-section')].find(panel=>panel.querySelector('h2')?.textContent==='Turudgifter og kvitteringer');if(expensePanel)[...expensePanel.querySelectorAll('tbody tr')].forEach((row,index)=>{if(report.expenses[index]?.receiptFile)return;row.cells[row.cells.length-1].innerHTML='<span class="missing-receipt-label">Kvittering mangler</span>'});const pending=report.expenses.filter(item=>(item.status||'pending')==='pending'),approvalPanel=$('.expense-approval-panel');if(approvalPanel)[...approvalPanel.querySelectorAll('tbody tr')].forEach((row,index)=>{if(pending[index]?.receiptFile)return;row.cells[3].innerHTML='<span class="missing-receipt-label">Mangler</span>';const approve=row.querySelector('[data-approve-expense]');if(approve){approve.disabled=true;approve.title='Kvittering skal tilføjes fra turens udgiftsmappe'}})}catch(error){toast(error.message)}};

// Operations calendar with today, week and month views.
const newTripBeforeDuration=$('#newTrip').onclick;
$('#newTrip').onclick=()=>{newTripBeforeDuration();const form=$('#createTrip');if(!form||form.durationMinutes)return;form.departureAt.closest('label').insertAdjacentHTML('afterend','<label>Forventet varighed<select name="durationMinutes"><option value="240">4 timer</option><option value="360">6 timer</option><option value="480" selected>8 timer</option><option value="600">10 timer</option><option value="720">12 timer</option><option value="1440">24 timer</option></select></label>')};

function calendarDayKey(value){const day=new Date(value);return`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`}
function calendarAnchor(){return new Date(`${state.calendarDate||calendarDayKey(new Date())}T12:00:00`)}
function calendarMonday(value){const day=new Date(value),offset=(day.getDay()+6)%7;day.setDate(day.getDate()-offset);day.setHours(0,0,0,0);return day}
function calendarStatus(trip){const now=Date.now(),start=new Date(trip.departureAt).getTime(),end=start+Number(trip.durationMinutes||480)*60000;if(trip.status==='cancelled')return'cancelled';if(trip.status==='completed'||now>end)return'completed';if(now>=start&&now<=end)return'underway';if(start-now<=2*60*60*1000&&start>now)return'checkin';return'planned'}
function calendarStatusLabel(status){return({planned:'Planlagt',checkin:'Check-in åbner',underway:'Undervejs',completed:'Afsluttet',cancelled:'Aflyst'})[status]||'Planlagt'}
function calendarConflicts(trips){const conflicts=new Map(trips.map(trip=>[trip.id,new Set()]));for(let i=0;i<trips.length;i++)for(let j=i+1;j<trips.length;j++){const a=trips[i],b=trips[j],aStart=new Date(a.departureAt).getTime(),aEnd=aStart+Number(a.durationMinutes||480)*60000,bStart=new Date(b.departureAt).getTime(),bEnd=bStart+Number(b.durationMinutes||480)*60000;if(aStart>=bEnd||bStart>=aEnd)continue;const labels=[];if(a.busId&&a.busId===b.busId)labels.push(`Bus: ${a.bus?.name||'samme bus'}`);const aDrivers=[a.primaryDriverId,a.secondaryDriverId].filter(Boolean),bDrivers=[b.primaryDriverId,b.secondaryDriverId].filter(Boolean),driver=aDrivers.find(id=>bDrivers.includes(id));if(driver)labels.push(`Chauffør: ${state.drivers?.find(item=>item.id===driver)?.name||a.primaryDriver||a.secondaryDriver||'samme chauffør'}`);labels.forEach(label=>{conflicts.get(a.id).add(label);conflicts.get(b.id).add(label)})}return conflicts}
function filteredCalendarTrips(){const filter=state.calendarFilters||{},query=(filter.query||'').toLowerCase();return state.trips.filter(trip=>(!query||`${trip.title} ${trip.origin?.name||''} ${trip.destination?.name||''} ${trip.primaryDriver||''} ${trip.bus?.name||''}`.toLowerCase().includes(query))&&(!filter.busId||trip.busId===Number(filter.busId))&&(!filter.driverId||[trip.primaryDriverId,trip.secondaryDriverId].includes(Number(filter.driverId)))&&(!filter.status||calendarStatus(trip)===filter.status)).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt))}
function calendarTripCard(trip,conflicts,compact=false){const status=calendarStatus(trip),capacity=trip.seatCount||trip.bus?.seatCount||0,occupancy=capacity?Math.round(trip.counts.passengers/capacity*100):0,issues=conflicts.get(trip.id)?.size||0,end=new Date(new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000);return`<button class="ops-trip-card status-${status} ${compact?'compact':''}" data-calendar-trip="${trip.id}"><span class="ops-trip-time"><b>${new Date(trip.departureAt).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'})}</b><small>til ${end.toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'})}</small></span><span class="ops-trip-main"><i>${calendarStatusLabel(status)}</i><strong>${esc(trip.title)}</strong><small>${esc(trip.origin?.name||'–')} → ${esc(trip.destination?.name||'–')}</small></span>${compact?'':`<span class="ops-trip-staff"><small>${esc(trip.bus?.name||'Ingen bus')}</small><b>${esc(trip.primaryDriver||'Ingen chauffør')}</b></span><span class="ops-trip-progress"><b>${trip.counts.checkedIn}/${trip.counts.passengers}</b><small>checket ind</small><i><em style="width:${trip.counts.passengers?Math.round(trip.counts.checkedIn/trip.counts.passengers*100):0}%"></em></i></span><span class="ops-trip-occupancy"><b>${trip.counts.passengers}/${capacity||'–'}</b><small>${occupancy}% belægning</small></span>`}${issues?`<span class="ops-conflict-badge" title="Ressourcekonflikt">! ${issues}</span>`:''}</button>`}
function calendarTodayView(trips,conflicts,anchor){const dayTrips=trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(anchor));return`<div class="ops-day-heading"><span>${anchor.toLocaleDateString('da-DK',{weekday:'long'})}</span><strong>${anchor.toLocaleDateString('da-DK',{day:'numeric',month:'long',year:'numeric'})}</strong></div><div class="ops-timeline">${dayTrips.length?dayTrips.map(trip=>`<div class="ops-timeline-row"><div><i></i></div>${calendarTripCard(trip,conflicts)}</div>`).join(''):'<div class="ops-calendar-empty"><strong>Ingen ture denne dag</strong><span>Vælg en anden dato eller opret en ny tur.</span></div>'}</div>`}
function calendarWeekView(trips,conflicts,anchor){const start=calendarMonday(anchor);return`<div class="ops-week">${Array.from({length:7},(_,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);const dayTrips=trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(day));return`<section class="ops-week-day ${calendarDayKey(day)===calendarDayKey(new Date())?'today':''}"><header><span>${day.toLocaleDateString('da-DK',{weekday:'short'})}</span><strong>${day.getDate()}</strong><small>${dayTrips.length} ture</small></header><div>${dayTrips.map(trip=>calendarTripCard(trip,conflicts,true)).join('')||'<p>Ingen ture</p>'}</div></section>`}).join('')}</div>`}
function calendarMonthView(trips,conflicts,anchor){const first=new Date(anchor.getFullYear(),anchor.getMonth(),1),start=calendarMonday(first),weekdays=['Man','Tir','Ons','Tor','Fre','Lør','Søn'];return`<div class="ops-month-weekdays">${weekdays.map(day=>`<span>${day}</span>`).join('')}</div><div class="ops-month">${Array.from({length:42},(_,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);const dayTrips=trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(day));return`<section class="ops-month-day ${dayTrips.length?'has-trips':''} ${day.getMonth()!==anchor.getMonth()?'muted':''} ${calendarDayKey(day)===calendarDayKey(new Date())?'today':''}"><header><strong>${day.getDate()}</strong><span>${dayTrips.length||''}</span></header><div>${dayTrips.slice(0,3).map(trip=>calendarTripCard(trip,conflicts,true)).join('')}${dayTrips.length>3?`<button class="more-trips" data-calendar-mode-day="${calendarDayKey(day)}">+ ${dayTrips.length-3} flere</button>`:''}</div></section>`}).join('')}</div>`}

renderCalendar=function(){state.trip=null;activate('calendar');setTitle('Turkalender','DRIFTSCENTER');state.calendarMode=state.calendarMode||'today';state.calendarDate=state.calendarDate||calendarDayKey(new Date());state.calendarFilters=state.calendarFilters||{};const anchor=calendarAnchor(),trips=filteredCalendarTrips(),activeTrips=state.trips.filter(trip=>!['completed','cancelled'].includes(calendarStatus(trip))),conflicts=calendarConflicts(activeTrips),conflictTrips=activeTrips.filter(trip=>conflicts.get(trip.id)?.size).length,missingStaff=activeTrips.filter(trip=>!trip.busId||!trip.primaryDriverId).length,missingReceipts=state.trips.reduce((sum,trip)=>sum+Number(trip.counts.missingReceipts||0),0),unsettled=state.trips.reduce((sum,trip)=>sum+Number(trip.counts.unsettledCash||0),0),unpaid=state.trips.reduce((sum,trip)=>sum+Number(trip.counts.unpaid||0),0),buses=[...new Map(state.trips.filter(trip=>trip.busId).map(trip=>[trip.busId,trip.bus])).entries()],drivers=[...new Map(state.trips.flatMap(trip=>[[trip.primaryDriverId,trip.primaryDriver],[trip.secondaryDriverId,trip.secondaryDriver]]).filter(([id])=>id)).entries()];let title=anchor.toLocaleDateString('da-DK',{day:'numeric',month:'long',year:'numeric'}),body=calendarTodayView(trips,conflicts,anchor);if(state.calendarMode==='week'){const start=calendarMonday(anchor),end=new Date(start);end.setDate(start.getDate()+6);title=`${start.toLocaleDateString('da-DK',{day:'numeric',month:'short'})} – ${end.toLocaleDateString('da-DK',{day:'numeric',month:'short',year:'numeric'})}`;body=calendarWeekView(trips,conflicts,anchor)}if(state.calendarMode==='month'){title=anchor.toLocaleDateString('da-DK',{month:'long',year:'numeric'});body=calendarMonthView(trips,conflicts,anchor)}$('#view').innerHTML=`<section class="ops-alert-strip"><div class="${conflictTrips?'danger':'ok'}"><b>${conflictTrips}</b><span>Ressourcekonflikter</span></div><div class="${missingStaff?'warning':'ok'}"><b>${missingStaff}</b><span>Mangler bemanding/bus</span></div><div class="${missingReceipts?'warning':'ok'}"><b>${missingReceipts}</b><span>Mangler kvittering</span></div><div class="${unsettled?'warning':'ok'}"><b>${unsettled}</b><span>Uafleverede betalinger</span></div><div class="${unpaid?'warning':'ok'}"><b>${unpaid}</b><span>Ubetalte salg</span></div></section><section class="ops-calendar-shell"><header class="ops-calendar-toolbar"><div class="ops-view-switch"><button data-calendar-mode="today" class="${state.calendarMode==='today'?'active':''}">I dag</button><button data-calendar-mode="week" class="${state.calendarMode==='week'?'active':''}">Uge</button><button data-calendar-mode="month" class="${state.calendarMode==='month'?'active':''}">Måned</button></div><div class="ops-date-nav"><button id="calendarPrevious" aria-label="Forrige">‹</button><strong>${title}</strong><button id="calendarNext" aria-label="Næste">›</button><button id="calendarToday">I dag</button></div></header><div class="ops-calendar-filters"><label class="ops-calendar-search">⌕<input id="calendarSearch" value="${esc(state.calendarFilters.query||'')}" placeholder="Søg rute, chauffør eller bus"></label><select id="calendarBus"><option value="">Alle busser</option>${buses.map(([id,bus])=>`<option value="${id}" ${String(state.calendarFilters.busId)===String(id)?'selected':''}>${esc(bus?.name||'Ukendt bus')}</option>`).join('')}</select><select id="calendarDriver"><option value="">Alle chauffører</option>${drivers.map(([id,name])=>`<option value="${id}" ${String(state.calendarFilters.driverId)===String(id)?'selected':''}>${esc(name||'Ukendt')}</option>`).join('')}</select><select id="calendarStatus"><option value="">Alle statusser</option>${['planned','checkin','underway','completed','cancelled'].map(status=>`<option value="${status}" ${state.calendarFilters.status===status?'selected':''}>${calendarStatusLabel(status)}</option>`).join('')}</select><button class="mini" id="calendarReset">Nulstil</button></div><div class="ops-calendar-body">${body}</div></section><aside class="ops-trip-drawer" id="opsTripDrawer" hidden></aside><div class="ops-drawer-backdrop" id="opsDrawerBackdrop" hidden></div>`;wireOperationsCalendar(conflicts)};

function wireOperationsCalendar(conflicts){$$('[data-calendar-mode]').forEach(button=>button.onclick=()=>{state.calendarMode=button.dataset.calendarMode;if(state.calendarMode==='today')state.calendarDate=calendarDayKey(new Date());renderCalendar()});const move=direction=>{const anchor=calendarAnchor();if(state.calendarMode==='month')anchor.setMonth(anchor.getMonth()+direction);else anchor.setDate(anchor.getDate()+direction*(state.calendarMode==='week'?7:1));state.calendarDate=calendarDayKey(anchor);renderCalendar()};$('#calendarPrevious').onclick=()=>move(-1);$('#calendarNext').onclick=()=>move(1);$('#calendarToday').onclick=()=>{state.calendarDate=calendarDayKey(new Date());renderCalendar()};const updateFilters=()=>{state.calendarFilters={query:$('#calendarSearch').value,busId:$('#calendarBus').value,driverId:$('#calendarDriver').value,status:$('#calendarStatus').value};renderCalendar()};$('#calendarSearch').oninput=event=>{state.calendarFilters.query=event.target.value;clearTimeout(state.calendarSearchTimer);state.calendarSearchTimer=setTimeout(()=>{renderCalendar();const input=$('#calendarSearch');input.focus();input.setSelectionRange(input.value.length,input.value.length)},300)};['#calendarBus','#calendarDriver','#calendarStatus'].forEach(selector=>$(selector).onchange=updateFilters);$('#calendarReset').onclick=()=>{state.calendarFilters={};renderCalendar()};$$('[data-calendar-trip]').forEach(button=>button.onclick=()=>openCalendarDrawer(Number(button.dataset.calendarTrip),conflicts));$$('[data-calendar-mode-day]').forEach(button=>button.onclick=()=>{state.calendarDate=button.dataset.calendarModeDay;state.calendarMode='today';renderCalendar()})}
function openCalendarDrawer(id,conflicts){const trip=state.trips.find(item=>item.id===id),drawer=$('#opsTripDrawer'),backdrop=$('#opsDrawerBackdrop');if(!trip||!drawer)return;const conflictList=[...(conflicts.get(id)||[])],capacity=trip.seatCount||trip.bus?.seatCount||0,status=calendarStatus(trip);drawer.innerHTML=`<button class="ops-drawer-close" id="closeOpsDrawer">×</button><small>DRIFTSDETALJER</small><h2>${esc(trip.title)}</h2><p>${date(trip.departureAt)} · ${calendarStatusLabel(status)}</p><div class="ops-drawer-route"><span>${esc(trip.origin?.name||'–')}</span><i>→</i><span>${esc(trip.destination?.name||'–')}</span></div>${conflictList.length?`<div class="ops-drawer-warning"><strong>Ressourcekonflikt</strong>${conflictList.map(item=>`<span>${esc(item)}</span>`).join('')}</div>`:''}<div class="ops-drawer-details"><div><span>Bus</span><strong>${esc(trip.bus?.name||'Ikke valgt')}</strong></div><div><span>Primær chauffør</span><strong>${esc(trip.primaryDriver||'Ikke valgt')}</strong></div><div><span>Sekundær chauffør</span><strong>${esc(trip.secondaryDriver||'Ikke valgt')}</strong></div><div><span>Salgschef</span><strong>${esc(trip.salesManager||'Ikke valgt')}</strong></div></div><div class="ops-drawer-numbers"><div><strong>${trip.counts.passengers}/${capacity||'–'}</strong><span>Passagerer</span></div><div><strong>${trip.counts.checkedIn}/${trip.counts.passengers}</strong><span>Check-in</span></div><div><strong>${trip.counts.baggage}</strong><span>Bagage</span></div></div><div class="ops-drawer-tasks">${trip.counts.unpaid?`<span>${trip.counts.unpaid} ubetalte salg</span>`:''}${trip.counts.missingReceipts?`<span>${trip.counts.missingReceipts} manglende kvitteringer</span>`:''}${trip.counts.unsettledCash?`<span>${trip.counts.unsettledCash} uafleverede betalinger</span>`:''}</div><div class="ops-drawer-actions"><button class="primary" data-calendar-open="${id}">Åbn tur</button><button data-calendar-checkin="${id}">Åbn check-in</button>${['admin','sales_manager'].includes(state.user.role)?`<button data-calendar-passenger="${id}">+ Passager</button>`:''}${state.user.role==='admin'?`<button data-calendar-economy="${id}">Se økonomi</button>`:''}</div>`;drawer.hidden=false;backdrop.hidden=false;const close=()=>{drawer.hidden=true;backdrop.hidden=true};$('#closeOpsDrawer').onclick=close;backdrop.onclick=close;$('[data-calendar-open]').onclick=()=>openCalendarTrip(id);$('[data-calendar-checkin]').onclick=()=>openCalendarTrip(id,'checkin');$('[data-calendar-passenger]')?.addEventListener('click',()=>openCalendarTrip(id,'passengers',true));$('[data-calendar-economy]')?.addEventListener('click',async()=>{await renderReports();const select=$('#economyTrip');if(select){select.value=String(id);select.dispatchEvent(new Event('change'))}})}
async function openCalendarTrip(id,tab,focusForm=false){await openTrip(id);if(tab){state.tab=tab;renderTrip()}const back=$('#back');if(back)back.onclick=renderCalendar;if(focusForm)setTimeout(()=>$('#passengerForm')?.scrollIntoView({behavior:'smooth',block:'start'}))}

// Role-based dashboard: every employee sees the work that matters now.
function dashboardActionCard(kind,count,title,text,action){return`<button class="dashboard-action-card ${count?'attention':'ok'}" data-dashboard-action="${action}"><span class="dashboard-action-icon">${kind}</span><strong>${count}</strong><div><b>${title}</b><small>${text}</small></div><i>›</i></button>`}
function dashboardQuickButton(icon,title,text,action){return`<button data-dashboard-quick="${action}"><span>${icon}</span><div><strong>${title}</strong><small>${text}</small></div><b>›</b></button>`}
function dashboardNextTrip(trip,conflicts){if(!trip)return'<div class="dashboard-no-trip"><strong>Ingen kommende ture</strong><span>Der er ingen aktive afgange i kalenderen.</span></div>';const status=calendarStatus(trip),capacity=trip.seatCount||trip.bus?.seatCount||0,pct=trip.counts.passengers?Math.round(trip.counts.checkedIn/trip.counts.passengers*100):0;return`<div class="dashboard-next-trip"><div class="dashboard-next-time"><small>${new Date(trip.departureAt).toLocaleDateString('da-DK',{weekday:'short',day:'numeric',month:'short'})}</small><strong>${new Date(trip.departureAt).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'})}</strong><span>${calendarStatusLabel(status)}</span></div><div class="dashboard-next-main"><h3>${esc(trip.title)}</h3><p>${esc(trip.origin?.name||'–')} → ${esc(trip.destination?.name||'–')}</p><div><span>${esc(trip.bus?.name||'Ingen bus')}</span><span>${esc(trip.primaryDriver||'Ingen chauffør')}</span></div></div><div class="dashboard-next-progress"><span><b>${trip.counts.checkedIn}</b> af ${trip.counts.passengers} checket ind</span><i><em style="width:${pct}%"></em></i><small>${trip.counts.passengers}/${capacity||'–'} sæder · ${trip.counts.baggage} bagage</small></div>${conflicts.get(trip.id)?.size?'<div class="dashboard-next-warning">! Ressourcekonflikt</div>':''}<div class="dashboard-next-actions"><button class="primary" data-dashboard-open-trip="${trip.id}">Åbn tur</button><button data-dashboard-checkin="${trip.id}">Check-in</button></div></div>`}

renderDashboard=async function(){state.trip=null;activate('dashboard');setTitle('Mit overblik','DAGENS DRIFT');let dashboard;try{dashboard=await api('/api/dashboard')}catch(error){toast(error.message);return}if(!$('.nav[data-view="dashboard"]')?.classList.contains('active'))return;const now=new Date(),activeTrips=state.trips.filter(trip=>!['completed','cancelled'].includes(calendarStatus(trip))).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt)),next=activeTrips.find(trip=>new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000>Date.now()),todayTrips=state.trips.filter(trip=>calendarDayKey(trip.departureAt)===calendarDayKey(now)).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt)),conflicts=calendarConflicts(activeTrips),conflictCount=activeTrips.filter(trip=>conflicts.get(trip.id)?.size).length,hour=now.getHours(),greeting=hour<10?'Godmorgen':hour<18?'Goddag':'Godaften',firstName=state.user.name.split(' ')[0],role=state.user.role;let actions='',quick='';if(role==='admin'){actions=dashboardActionCard('!',conflictCount,'Planlægningskonflikter','Bus eller chauffør overlapper','calendar')+dashboardActionCard('▧',dashboard.pendingExpenses,'Udgifter afventer','Kræver godkendelse','economy')+dashboardActionCard('⌑',dashboard.missingReceipts,'Kvitteringer mangler','Kan ikke godkendes endnu','economy')+dashboardActionCard('¤',dashboard.cashHeld.payments,'Uafleverede betalinger','Kontanter hos personale','economy');quick=dashboardQuickButton('+','Opret ny tur','Planlæg afgang og bemanding','new-trip')+dashboardQuickButton('□','Åbn kalender','Se hele driften','calendar')+dashboardQuickButton('♙','Chauffører','Administrer personale','drivers')+dashboardQuickButton('◫','Salg og økonomi','Kontanter, udgifter og resultat','economy')}else if(role==='driver'){actions=dashboardActionCard('✓',next?Math.max(0,next.counts.passengers-next.counts.checkedIn):0,'Passagerer afventer','På din næste tur','checkin')+dashboardActionCard('▣',dashboard.openBaggage,'Aktiv bagage','Skal håndteres på ture','calendar')+dashboardActionCard('¤',dashboard.cashHeld.payments,'Kontanter hos dig','Skal senere afstemmes','cash')+dashboardActionCard('⌑',dashboard.missingReceipts,'Kvitteringer mangler','Tilføj bilag på turen','expenses');quick=dashboardQuickButton('✓','Åbn check-in','Start med næste tur','checkin')+dashboardQuickButton('□','Mine ture','Åbn driftskalenderen','calendar')+dashboardQuickButton('⌑','Registrer udgift','Tag billede af kvittering','expenses')+dashboardQuickButton('¤','Kontantafstemning','Se dit kontantansvar','cash')}else{actions=dashboardActionCard('□',todayTrips.length,'Dagens ture','Du kan arbejde ved startstederne','calendar')+dashboardActionCard('!',dashboard.unpaid,'Ubetalte salg','Billetter og bagage','checkin')+dashboardActionCard('▣',dashboard.openBaggage,'Aktiv bagage','Modtagelse og udlevering','calendar')+dashboardActionCard('¤',dashboard.cashHeld.payments,'Kontanter hos dig','Skal senere afstemmes','cash');quick=dashboardQuickButton('✓','Åbn check-in','Betjen næste startsted','checkin')+dashboardQuickButton('+','Sælg billet','Tilføj passager på næste tur','passenger')+dashboardQuickButton('▣','Registrer bagage','Modtag bagage ved startstedet','baggage')+dashboardQuickButton('¤','Kontantafstemning','Se modtagne betalinger','cash')}
  const roleText=role==='admin'?'Her er virksomhedens vigtigste opgaver lige nu.':role==='driver'?'Her er dine afgange og opgaver for i dag.':'Her er dagens afgange, salg og betalinger ved startstederne.';
  $('#view').innerHTML=`<section class="dashboard-welcome"><div><small>${now.toLocaleDateString('da-DK',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</small><h2>${greeting}, ${esc(firstName)}</h2><p>${roleText}</p></div><span class="dashboard-live"><i></i> Live driftsstatus</span></section><section class="dashboard-action-section"><header><h3>Kræver handling</h3><span>${[...new DOMParser().parseFromString(actions,'text/html').querySelectorAll('.attention')].length} områder</span></header><div class="dashboard-action-grid">${actions}</div></section><div class="dashboard-workspace"><section class="dashboard-next-panel"><header><div><small>NÆSTE AFGANG</small><h3>${next?'Klar til drift':'Ingen planlagt afgang'}</h3></div><button data-dashboard-action="calendar">Se kalender →</button></header>${dashboardNextTrip(next,conflicts)}</section><section class="dashboard-quick-panel"><header><small>HURTIGE HANDLINGER</small><h3>Hvad vil du gøre?</h3></header><div>${quick}</div></section></div><div class="dashboard-lower"><section class="dashboard-today-panel"><header><div><small>DAGENS TIDSLINJE</small><h3>${todayTrips.length} ${todayTrips.length===1?'afgang':'afgange'} i dag</h3></div><button data-dashboard-action="calendar">Åbn kalender</button></header><div>${todayTrips.length?todayTrips.map(trip=>calendarTripCard(trip,conflicts,true)).join(''):'<div class="dashboard-empty-small">Ingen ture i dag</div>'}</div></section><section class="dashboard-money-panel"><header><small>${role==='admin'?'DAGENS SALG':'DIT KONTANTANSVAR'}</small><h3>${role==='admin'?'Billetter og bagage':'Kontanter hos dig'}</h3></header>${role==='admin'?`<div class="dashboard-sales-grid"><div><span>Billetter · ${dashboard.todayTicketSales}</span>${economyValues(dashboard.todayTicketRevenue,'all',true)}</div><div><span>Bagage · ${dashboard.todayBaggageSales}</span>${economyValues(dashboard.todayBaggageRevenue,'all',true)}</div></div>`:`<div class="dashboard-cash-total"><span>${dashboard.cashHeld.payments} betalinger</span>${economyValues(dashboard.cashHeld,'all',true)}</div>`}${role==='admin'&&dashboard.cashHeld.byPerson.length?`<div class="dashboard-holder-list">${dashboard.cashHeld.byPerson.map(person=>`<div><span>${esc(person.userName)}<small>${person.payments} betalinger</small></span><b>${money(person.DKK,'DKK')} · ${money(person.EUR,'EUR')}</b></div>`).join('')}</div>`:''}<button data-dashboard-action="${role==='admin'?'economy':'cash'}">${role==='admin'?'Åbn salg og økonomi':'Åbn kontantafstemning'} →</button></section></div>`;wireRoleDashboard(next)};

function wireRoleDashboard(next){const act=async action=>{if(action==='calendar')return renderCalendar();if(action==='economy')return renderReports();if(action==='drivers')return renderDrivers();if(action==='new-trip')return $('#newTrip').click();if(!next)return toast('Der er ingen kommende tur');if(action==='checkin')return openDashboardTrip(next.id,'checkin');if(action==='passenger')return openDashboardTrip(next.id,'passengers',true);if(action==='baggage')return openDashboardTrip(next.id,'baggage');if(action==='expenses')return openDashboardTrip(next.id,'expenses');if(action==='cash')return openDashboardTrip(next.id,'settlements')};$$('[data-dashboard-action]').forEach(button=>button.onclick=()=>act(button.dataset.dashboardAction));$$('[data-dashboard-quick]').forEach(button=>button.onclick=()=>act(button.dataset.dashboardQuick));$$('[data-dashboard-open-trip]').forEach(button=>button.onclick=()=>openDashboardTrip(Number(button.dataset.dashboardOpenTrip)));$$('[data-dashboard-checkin]').forEach(button=>button.onclick=()=>openDashboardTrip(Number(button.dataset.dashboardCheckin),'checkin'));$$('.dashboard-today-panel [data-calendar-trip]').forEach(button=>button.onclick=()=>openDashboardTrip(Number(button.dataset.calendarTrip)))}
async function openDashboardTrip(id,tab,focusForm=false){await openTrip(id);if(tab){state.tab=tab;renderTrip()}const back=$('#back');if(back)back.onclick=renderDashboard;if(focusForm)setTimeout(()=>$('#passengerForm')?.scrollIntoView({behavior:'smooth',block:'start'}))}

// Administratorens turudgifter vises som adskilte mapper, én planlagt tur ad gangen.
const reportsBeforeTripExpenseBrowser=renderReports;
renderReports=async function(){
  await reportsBeforeTripExpenseBrowser();
  if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;
  try{
    const report=await api('/api/reports');
    renderTripExpenseBrowser(report);
  }catch(error){toast(error.message)}
};

function expenseTotalsForTrip(expenses,status){
  return ['DKK','EUR'].reduce((totals,currency)=>{
    totals[currency]=expenses.filter(expense=>(!status||(expense.status||'pending')===status)&&expense.currency===currency).reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    return totals;
  },{});
}

function plannedExpenseTrips(){
  const now=Date.now(),trips=(state.trips||[]).filter(trip=>trip.status!=='cancelled');
  const active=trips.filter(trip=>new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000>=now).sort((a,b)=>new Date(a.departureAt)-new Date(b.departureAt));
  const previous=trips.filter(trip=>new Date(trip.departureAt).getTime()+Number(trip.durationMinutes||480)*60000<now).sort((a,b)=>new Date(b.departureAt)-new Date(a.departureAt));
  return [...active,...previous];
}

function renderTripExpenseBrowser(report){
  $('#tripExpenseBrowser')?.remove();
  [...$$('.report-section')].find(panel=>panel.querySelector('h2')?.textContent==='Turudgifter og kvitteringer')?.remove();
  $('.expense-approval-panel')?.remove();
  const trips=plannedExpenseTrips(),expenses=report.expenses||[];
  const anchor=$('.advanced-trip-economy')||$('.economy-control');
  if(!anchor)return;
  if(!trips.length){
    anchor.insertAdjacentHTML('afterend','<section class="trip-expense-browser empty-trip-expenses" id="tripExpenseBrowser"><span class="trip-expense-folder-icon">▧</span><div><small>TURUDGIFTSMAPPER</small><h2>Ingen planlagte ture</h2><p>Opret en tur i kalenderen. Derefter får turen automatisk sin egen udgiftsmappe.</p></div></section>');
    return;
  }
  const firstWithAction=trips.find(trip=>expenses.some(expense=>expense.tripId===trip.id&&((expense.status||'pending')==='pending'||!expense.receiptFile))),firstUpcoming=trips.find(trip=>new Date(trip.departureAt)>new Date());
  if(!trips.some(trip=>trip.id===Number(state.expenseTripId)))state.expenseTripId=firstWithAction?.id||firstUpcoming?.id||trips[0].id;
  const selected=trips.find(trip=>trip.id===Number(state.expenseTripId)),selectedIndex=trips.findIndex(trip=>trip.id===selected.id),selectedExpenses=expenses.filter(expense=>expense.tripId===selected.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  const approved=expenseTotalsForTrip(selectedExpenses,'approved'),pending=expenseTotalsForTrip(selectedExpenses,'pending'),missing=selectedExpenses.filter(expense=>!expense.receiptFile).length,privateOpen=selectedExpenses.filter(expense=>(expense.paymentMethod||'cash')==='private'&&(expense.reimbursementStatus||'pending')!=='paid'&&(expense.status||'pending')!=='rejected').length;
  const tripButtons=trips.map(trip=>{const tripExpenses=expenses.filter(expense=>expense.tripId===trip.id),tripPending=tripExpenses.filter(expense=>(expense.status||'pending')==='pending').length,tripMissing=tripExpenses.filter(expense=>!expense.receiptFile).length;return`<button class="trip-expense-folder ${trip.id===selected.id?'active':''}" data-expense-trip="${trip.id}"><span class="trip-expense-folder-icon">▧</span><span><strong>${esc(trip.title)}</strong><small>${date(trip.departureAt)} · ${tripExpenses.length} udgifter</small></span>${tripPending||tripMissing?`<b>${tripPending+tripMissing}</b>`:'<i>✓</i>'}</button>`}).join('');
  const options=trips.map(trip=>`<option value="${trip.id}" ${trip.id===selected.id?'selected':''}>${new Date(trip.departureAt).toLocaleDateString('da-DK')} · ${esc(trip.title)}</option>`).join('');
  const rows=selectedExpenses.length?selectedExpenses.map(adminTripExpenseCard).join(''):'<div class="trip-expense-empty"><span>✓</span><strong>Ingen udgifter på denne tur</strong><p>Når en chauffør eller administrator registrerer en udgift, vises den kun i denne mappe.</p></div>';
  anchor.insertAdjacentHTML('afterend',`<section class="trip-expense-browser" id="tripExpenseBrowser"><header class="trip-expense-browser-head"><div><small>ADMINISTRATOR · TURUDGIFTSMAPPER</small><h2>Udgifter adskilt efter tur</h2><p>Vælg en tur for kun at se dens udgifter, bilag og godkendelser.</p></div><div class="trip-expense-navigation"><button id="previousExpenseTrip" aria-label="Forrige turs udgifter" ${selectedIndex===0?'disabled':''}>‹</button><label>Vælg tur<select id="expenseTripNavigator">${options}</select></label><button id="nextExpenseTrip" aria-label="Næste turs udgifter" ${selectedIndex===trips.length-1?'disabled':''}>›</button></div></header><div class="trip-expense-browser-layout"><nav class="trip-expense-folders" aria-label="Planlagte tures udgiftsmapper">${tripButtons}</nav><div class="trip-expense-selected"><header><div><small>${calendarStatusLabel(calendarStatus(selected))} · ${date(selected.departureAt)}</small><h3>${esc(selected.title)}</h3><p>${esc(selected.origin?.name||'–')} → ${esc(selected.destination?.name||'–')} · ${esc(selected.bus?.name||'Ingen bus')}</p></div><button class="mini" id="openSelectedTripExpenses">Åbn turens udgiftsmappe →</button></header><div class="trip-expense-totals"><div class="approved"><span>Godkendt</span>${economyValues(approved,'all',true)}</div><div class="pending"><span>Afventer</span>${economyValues(pending,'all',true)}</div><div class="${missing?'attention':''}"><span>Mangler kvittering</span><strong>${missing}</strong></div><div class="${privateOpen?'attention':''}"><span>Private udlæg åbne</span><strong>${privateOpen}</strong></div></div><div class="admin-trip-expense-list">${rows}</div></div></div></section>`);
  wireTripExpenseBrowser(report,trips,selectedIndex,selected.id);
}

function adminTripExpenseCard(expense){
  const status=expense.status||'pending',missing=!expense.receiptFile,privatePending=(expense.paymentMethod||'cash')==='private'&&status==='approved'&&(expense.reimbursementStatus||'pending')!=='paid';
  return`<article class="admin-trip-expense-card"><span class="admin-expense-status ${status}">${expenseStatusLabel(status)}</span><div class="admin-expense-main"><small>${date(expense.expenseDate||expense.createdAt)} · ${expenseMethodLabel(expense.paymentMethod||'cash')}</small><h4>${esc(expense.category)}</h4><p>${esc(expense.description||'Ingen beskrivelse')}</p><span>Betalt af <b>${esc(expense.paidByName||expense.createdByName||'Ukendt')}</b> · registreret af ${esc(expense.createdByName||'Ukendt')}</span></div><strong class="admin-expense-amount">${money(expense.amount,expense.currency)}</strong><div class="admin-expense-receipt ${missing?'missing':''}">${missing?'<span>Kvittering mangler</span>':`<a href="/api/expenses/${expense.id}/receipt" target="_blank">Se kvittering ↗</a>`}</div><div class="admin-expense-actions">${status==='pending'?`<button class="mini done" data-admin-approve-expense="${expense.id}" ${missing?'disabled title="Kvittering mangler"':''}>Godkend</button><button class="mini danger" data-admin-reject-expense="${expense.id}">Afvis</button>`:''}${privatePending?`<button class="mini reimburse" data-admin-reimburse-expense="${expense.id}">Marker tilbagebetalt</button>`:''}</div>${expense.reviewNote?`<div class="admin-expense-note"><b>Kommentar:</b> ${esc(expense.reviewNote)}</div>`:''}</article>`;
}

function wireTripExpenseBrowser(report,trips,index,tripId){
  state.adminExpenseReport=report;
  $$('[data-expense-trip]').forEach(button=>button.onclick=()=>{state.expenseTripId=Number(button.dataset.expenseTrip);renderTripExpenseBrowser(report)});
  $('#expenseTripNavigator').onchange=event=>{state.expenseTripId=Number(event.target.value);renderTripExpenseBrowser(report)};
  $('#previousExpenseTrip').onclick=()=>{if(index>0){state.expenseTripId=trips[index-1].id;renderTripExpenseBrowser(report)}};
  $('#nextExpenseTrip').onclick=()=>{if(index<trips.length-1){state.expenseTripId=trips[index+1].id;renderTripExpenseBrowser(report)}};
  $('#openSelectedTripExpenses').onclick=async()=>{await openTrip(tripId);state.tab='expenses';renderTrip();const back=$('#back');if(back)back.onclick=renderReports};
  $$('[data-admin-approve-expense]').forEach(button=>button.onclick=()=>reviewAdminTripExpense(Number(button.dataset.adminApproveExpense),'approved'));
  $$('[data-admin-reject-expense]').forEach(button=>button.onclick=()=>reviewAdminTripExpense(Number(button.dataset.adminRejectExpense),'rejected'));
  $$('[data-admin-reimburse-expense]').forEach(button=>button.onclick=()=>reimburseAdminTripExpense(Number(button.dataset.adminReimburseExpense)));
}

async function reviewAdminTripExpense(id,status){
  let reviewNote='';
  if(status==='rejected'){const reason=prompt('Hvorfor afvises udgiften?');if(reason===null)return;reviewNote=reason}
  try{await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({status,reviewNote})});toast(status==='approved'?'Udgiften er godkendt':'Udgiften er afvist');await renderReports()}catch(error){toast(error.message)}
}

async function reimburseAdminTripExpense(id){
  if(!confirm('Bekræft, at det private udlæg er tilbagebetalt.'))return;
  try{await api(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({reimbursementStatus:'paid'})});toast('Udlægget er markeret som tilbagebetalt');await renderReports()}catch(error){toast(error.message)}
}

// Every baggage record is created with a trip-specific documentation photo.
baggageForm=function(){return`<section class="panel baggage-entry-panel"><div class="panel-head"><div><small>BAGAGEDOKUMENTATION</small><h2>Registrer bagage</h2></div><span class="baggage-photo-required">Foto påkrævet</span></div><form class="form" id="baggageForm" style="padding:20px"><label>Afsender<input name="senderName" required></label><label>Telefon<input name="phone" required></label><label>Fra<select name="pickupStopId">${stopOptions()}</select></label><label>Til<select name="destinationStopId">${stopOptions()}</select></label><label>Antal kolli<input name="pieces" type="number" min="1" value="1" required></label><label>Beskrivelse<input name="description" placeholder="Kuffert, pakke …"></label><label class="wide receipt-capture baggage-photo-capture"><span>Foto af bagagen <small>obligatorisk dokumentation</small></span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required><b>Tag billede eller vælg foto</b><em>JPG, PNG eller WebP · maks. 5 MB</em></label><label>Betaling<select name="paymentStatus"><option value="unpaid">Ikke betalt</option><option value="cash">Betalt kontant</option></select></label><label>Valuta<select name="paymentCurrency"><option value="DKK">DKK – Danske kroner</option><option value="EUR">EUR – Euro</option></select></label><label>Kontant beløb<input name="cashAmount" type="number" min="0" step="0.01" value="0"></label><label class="wide">Bemærkning<textarea name="notes" placeholder="Kendetegn, farve eller anden dokumentation"></textarea></label><button class="primary wide">Gem bagage med foto</button></form></section>`};

wireBaggageForm=function(){const form=$('#baggageForm'),photoInput=form.elements.photo,photoLabel=form.querySelector('.baggage-photo-capture b');photoInput.onchange=()=>{photoLabel.textContent=photoInput.files[0]?.name||'Tag billede eller vælg foto'};form.onsubmit=async event=>{event.preventDefault();const file=photoInput.files[0];if(!file)return toast('Tag eller vælg et billede af bagagen');if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Bagagebilledet skal være JPG, PNG eller WebP');if(file.size>5*1024*1024)return toast('Bagagebilledet må højst fylde 5 MB');try{const payload=Object.fromEntries(new FormData(form));delete payload.photo;Object.assign(payload,{photoName:file.name,photoType:file.type,photoData:await fileAsDataUrl(file)});const baggage=await api(`/api/trips/${state.trip.trip.id}/baggage`,{method:'POST',body:JSON.stringify(payload)});state.trip.baggage.push(baggage);toast(state.user.role==='driver'?'Bagagen er modtaget · pengene står hos dig':'Bagagen og billeddokumentationen er gemt');renderTrip()}catch(error){toast(error.message)}}};

const renderTabBeforeBaggagePhotos=renderTab;
renderTab=function(){renderTabBeforeBaggagePhotos();if(state.tab!=='baggage')return;$$('#tabContent [data-bag]').forEach(control=>{const item=state.trip.baggage.find(record=>record.id===Number(control.dataset.bag)),cell=control.closest('tr')?.cells[0];if(!item||!cell||cell.querySelector('.baggage-photo-link,.baggage-photo-missing'))return;cell.insertAdjacentHTML('beforeend',item.photoFile?`<a class="baggage-photo-link" href="/api/baggage/${item.id}/photo" target="_blank">▣ Se bagagefoto ↗</a>`:'<span class="baggage-photo-missing">Foto mangler</span>')})};

const reportsBeforeBaggagePhotos=renderReports;
renderReports=async function(){await reportsBeforeBaggagePhotos();if(!$('.nav[data-view="reports"]')?.classList.contains('active'))return;try{const report=await api('/api/reports'),panel=[...$$('.report-section')].find(section=>section.querySelector('h2')?.textContent==='Bagagesalg');if(!panel)return;[...panel.querySelectorAll('tbody tr')].forEach((row,index)=>{const item=report.baggage[index],cell=row.cells[0];if(!item||!cell||cell.querySelector('.baggage-photo-link,.baggage-photo-missing'))return;cell.insertAdjacentHTML('beforeend',item.photoFile?`<a class="baggage-photo-link" href="/api/baggage/${item.id}/photo" target="_blank">▣ Se dokumentationsfoto ↗</a>`:'<span class="baggage-photo-missing">Foto mangler</span>')})}catch(error){toast(error.message)}};

// Assigned drivers can sell a paid ticket in the bus. The cash is always assigned to the logged-in driver.
const renderTabBeforeDriverTicketSales=renderTab;
renderTab=function(){renderTabBeforeDriverTicketSales();if(state.user.role!=='driver'||state.tab!=='passengers')return;const layout=$('.passenger-layout');if(!layout)return;while(layout.children.length>1)layout.lastElementChild.remove();layout.insertAdjacentHTML('beforeend',passengerForm());const form=$('#passengerForm'),panel=form.closest('.panel'),heading=panel.querySelector('.panel-head');panel.classList.add('driver-ticket-panel');heading.innerHTML=`<div><small>BILLETSALG I BUSSEN</small><h2>Sælg ny billet</h2></div><span>Kontanter hos ${esc(state.user.name)}</span>`;heading.insertAdjacentHTML('afterend',`<div class="driver-ticket-note"><b>¤</b><span>Betalingen registreres automatisk hos dig og kommer med i turens kontantafstemning.</span></div>`);form.paymentStatus.innerHTML='<option value="cash">Betalt kontant i bussen</option>';form.paymentStatus.value='cash';form.querySelector('[data-free-ticket-field]')?.remove();const preferredStop=Number(state.currentCheckinStop)||state.trip.trip.originId;if([...form.pickupStopId.options].some(option=>Number(option.value)===preferredStop))form.pickupStopId.value=String(preferredStop);form.querySelector('button.primary').textContent='Sælg billet i bussen';wirePassengerForm();form.paymentStatus.dispatchEvent(new Event('change'))};

const checkInModeBeforeDriverTicketSales=renderCheckInMode;
renderCheckInMode=function(){checkInModeBeforeDriverTicketSales();if(state.user.role!=='driver'||!$('.checkin-command'))return;$('.checkin-command').insertAdjacentHTML('afterend','<button class="driver-ticket-shortcut" id="driverTicketShortcut"><b>＋</b><span><strong>Sælg billet i bussen</strong><small>Vælg et ledigt sæde og registrer betalingen</small></span><i>→</i></button>');$('#driverTicketShortcut').onclick=()=>{state.tab='passengers';state.selectedSeat=null;renderTrip()}};

const renderTabBeforeDriverBaggageIntake=renderTab;
renderTab=function(){renderTabBeforeDriverBaggageIntake();if(state.user.role!=='driver'||state.tab!=='baggage'||$('#baggageForm'))return;const layout=$('#tabContent .grid2');if(!layout)return;while(layout.children.length>1)layout.lastElementChild.remove();layout.insertAdjacentHTML('beforeend',baggageForm());const form=$('#baggageForm'),panel=form.closest('.panel'),heading=panel.querySelector('.panel-head');panel.classList.add('driver-baggage-panel');heading.innerHTML=`<div><small>BAGAGEMODTAGELSE I BUSSEN</small><h2>Modtag ny bagage</h2></div><span>Kontanter hos ${esc(state.user.name)}</span>`;heading.insertAdjacentHTML('afterend','<div class="driver-baggage-note"><b>▣</b><span>Tag et billede af bagagen. Betalingen registreres automatisk hos dig og kommer med i turens kontantafstemning.</span></div>');form.paymentStatus.innerHTML='<option value="cash">Betalt kontant i bussen</option>';form.paymentStatus.value='cash';const preferredStop=Number(state.currentCheckinStop)||state.trip.trip.originId;if([...form.pickupStopId.options].some(option=>Number(option.value)===preferredStop))form.pickupStopId.value=String(preferredStop);form.querySelector('button.primary').textContent='Modtag bagage i bussen';wireBaggageForm()};

const checkInModeBeforeDriverBaggageIntake=renderCheckInMode;
renderCheckInMode=function(){checkInModeBeforeDriverBaggageIntake();if(state.user.role!=='driver'||!$('#driverTicketShortcut'))return;$('#driverTicketShortcut').insertAdjacentHTML('afterend','<button class="driver-ticket-shortcut driver-baggage-shortcut" id="driverBaggageShortcut"><b>▣</b><span><strong>Modtag bagage i bussen</strong><small>Tag foto og registrer betalingen</small></span><i>→</i></button>');$('#driverBaggageShortcut').onclick=()=>{state.tab='baggage';renderTrip()}};
